import { View, Text, Pressable, StyleSheet } from "react-native";
import { useReducer } from "react";
import { registerRootComponent } from "expo";

function reducer(state, action) {
  if (action.type === "add") return state + 1;
  return state;
}

function App() {
  const [count, dispatch] = useReducer(reducer, 0);
  return (
    <View style={styles.s}>
      <Text nativeID="count" style={styles.c}>Сагс: {count}</Text>
      <Pressable nativeID="add" style={styles.b} onPress={() => dispatch({ type: "add" })}><Text style={styles.t}>Нэмэх</Text></Pressable>
    </View>
  );
}

const styles = StyleSheet.create({
  s: { flex: 1, gap: 16, padding: 24, alignItems: "center", justifyContent: "center" },
  c: { fontSize: 24, fontWeight: "bold" }, b: { backgroundColor: "#2563eb", padding: 14, borderRadius: 12 }, t: { color: "#fff", fontWeight: "bold" },
});

registerRootComponent(App);
